    ['Tip.Holiday.AlignLeft']= 'Places the event text on the left side of the button, right-aligned.',
    ['Tip.Holiday.GrowUp']= 'Makes the list grow upwards from the button instead of downwards.',
    ['Tip.Collection.Enable']= 'Adds extra information to the Collections window (mounts, pets, toys, heirlooms, appearances), the dressing room and the transmogrification window, such as collected counts, ability icons, set progress and class filter buttons.',
    ['Tip.Collection.Pets']= 'Shows owned/total count in the Pet Journal and the pet type and ability icons in the pet list and pet card.',
    ['Tip.Collection.Heirlooms']= 'Shows remaining upgrades, PvP mark, item level and stats on heirloom buttons. Not available on Timerunning characters.',
    ['Tip.Collection.WardrobeItems']= 'Shows collected counts per slot and extra appearance info on the Appearances items tab.',
    ['Tip.Collection.WardrobeSets']= 'Shows collection progress, expansion and limited-time mark for each set in the Sets list, and adds item links to the set details.',
    ['Tip.Collection.ClassList']= 'Shows a row of class and specialization buttons next to the Heirlooms and Appearances windows; click one to filter by that class.',
    ['Tip.Collection.ModelName']= 'Shows the item name under each appearance model in the transmogrification window. Hover the name to see the item tooltip.',
    ['Tip.Cursor.EnableGCD']= 'Shows a global cooldown (GCD) swipe next to the mouse cursor, so you can see the cooldown progress while casting.',
    ['Tip.Cursor.GCDReverse']= 'Reverses the direction of the GCD cooldown animation.',
    ['Tip.Cursor.GCDDrawBling']= 'Shows a flash effect when the global cooldown finishes.',
    ['Tip.Cursor.ClassColor']= 'Colors the cursor trail and the GCD animation with your class color.',
    ['Tip.Cursor.NoColor']= 'Does not tint the cursor trail or the GCD animation; the texture keeps its original colors.',
    ['Tip.Cursor.RandomTexture']= 'Picks random textures from the list: the cursor trail changes texture when you click (in combat, when you start moving), and the GCD animation changes after each cooldown.',
    ['Tip.Cursor.GCDTexture']= 'Uses this texture for the GCD animation (turns off random textures).',
    ['Tip.Target.Target']= 'Shows a marker texture on your current target\'s nameplate. Nameplates must be visible. Click the text to change its color; right-click to restore the default.',
    ['Tip.Target.InCombat']= 'Uses a different color for the target marker while you are in combat (red by default). Click the text to change it; right-click to restore the default.',
    ['Tip.Target.PointTop']= 'Places the target marker above the name on the nameplate.',
    ['Tip.Target.PointHealthBar']= 'Shows the target marker as a frame around the nameplate\'s health bar; the width and height sliders add extra size.',
    ['Tip.Target.PointLeft']= 'Places the target marker to the left of the nameplate (left of the raid marker or elite icon if shown).',
    ['Tip.Target.Texture']= 'Uses this texture as the target marker. Green names are textures you added yourself.',
    ['Tip.Target.Quest']= 'Shows quest progress on nameplates: mobs related to your active quests show the amount left or a quest icon, other players show friend and faction icons, and AI party members show their role. Not shown in raids, group instances, PvP areas or Mythic+ dungeons.',
    ['Tip.Target.QuestAllFaction']= 'Also shows the faction icon on nameplates of players from your own faction (by default only the opposite faction is shown).',
    ['Tip.Target.QuestClass']= 'Shows the class icon on other players\' nameplates.',
    ['Tip.Spell.Enable']= 'Enables the spell enhancements: spellbook, talents, specialization buttons, spell flyout text and action bar range color. Requires /reload.',
    ['Tip.Spell.Flyout']= 'Shows a short name or destination next to each spell in spell flyouts (portals, teleports, Call Pet...); for Hunter Call Pet it also shows the pet\'s abilities and specialization. Turning it off requires /reload.',
    ['Tip.Spell.RangeColor']= 'Tints action button icons red when your target is out of range of that ability. Turning it off requires /reload.',
    ['Tip.Spell.SpecButton']= 'Shows a button for each specialization; click one to switch to it. The current loot specialization is marked. Turning it off requires /reload.',
    ['Tip.Spell.Talents']= 'Shows the maximum rank on talent buttons (e.g. the "/2" in 1/2). Turning it off requires /reload.',
    ['Tip.Spell.SpellBook']= 'Enhances the spellbook: shows known/total spells in flyouts, spell requirements, your specialization role icon, and adds buttons on the left listing portal/teleport spells. Turning it off requires /reload.',
    ['Tip.Spell.SpecUIParent']= 'Places the specialization buttons freely on screen (Alt+right-drag to move) instead of attached to the spellbook window. In this mode you need Shift+left-click to switch specialization, and only the active specialization is shown in combat.',
    ['Tip.Color.Enable']= 'Adds enhancements to the color picker: value input fields, a history of used colors, saved colors and quick palettes.',
    ['Tip.Color.Show']= 'Shows or hides the addon\'s additions in the color picker (value fields, history and palettes). When off, the mouse wheel no longer adjusts brightness and opacity.',
    ['Tip.Color.ClearLog']= 'Clears the history of recently used colors. The submenu sets the maximum number of colors kept.',
    ['Tip.Color.MoreColors']= 'Adds an extra palette with more preset colors above the color picker.',
    ['Tip.Color.AutoHide']= 'Closes the color picker (canceling the change) when you click outside it, like the game does by default. Turn it off to keep it open.',
    ['Tip.Color.AutoShow']= 'Automatically opens the color picker when you log in.',
    ['Tip.Color.SlotChoose']= 'Saves the color currently selected in the picker to this slot.',
    ['Tip.Color.SlotDefault']= 'Resets this slot to its default color.',
    ['Tip.AuctionHouse.Enable']= 'Improves the Auction House: extra info in buy results, a quick list of bag items to sell, remembered prices and double-click to cancel auctions. It also shows in the account store how many items of each category you own.',
    ['Tip.AuctionHouse.BuyPlus']= 'In the Buy tab, shows how many of each item you own, whether it is already known or collected, its stats, and marks your own auctions. Double-clicking a row opens the buyout confirmation.',
    ['Tip.AuctionHouse.SellPlus']= 'In the Sell tab, adds a list of bag items that can be auctioned, remembers the last price used for each item, compares the price with the vendor price and lets you move on to the next item quickly.',
    ['Tip.AuctionHouse.AuctionsPlus']= 'In the Auctions tab, shows how many active auctions you have. Double-clicking one of your auctions cancels it instantly (the game may charge a cancellation fee).',
    ['Tip.AuctionHouse.SellList']= 'Shows the list of buttons with bag items that can be auctioned. Left-click places the item for sale; right-click marks it as hidden.',
    ['Tip.AuctionHouse.HideMarked']= 'Removes items marked as hidden (with right-click) from the sell list. When off, they stay in the list but dimmed.',
    ['Tip.AuctionHouse.ClearHidden']= 'Removes the hidden mark from all items and pets, after asking for confirmation.',
    ['Tip.AuctionHouse.SellQuality']= 'Only shows items of this quality or higher in the sell list.',
    ['Tip.AuctionHouse.GoToSell']= 'When you open the Auction House, automatically switches to the sell tab and places the first auctionable item from your bags.',
    ['Tip.AddOns.Enable']= 'Improves the AddOns window: a shortcut list to enable or disable addons, a bar with installed addon icons, saved addon profiles and extra info on each row.',
    ['Tip.AddOns.LeftList']= 'Shows the addons marked as shortcuts to the left of the AddOns window. Left-click enables or disables the addon; right-click finds it in the list.',
    ['Tip.AddOns.LeftListClear']= 'Empties the shortcut list, after asking for confirmation. It does not disable any addon.',
    ['Tip.AddOns.BottomList']= 'Shows a bar with the icons of installed addons (loaded ones first). Left-click filters the list by that addon; right-click finds it in the list.',
    ['Tip.AddOns.BottomListTop']= 'Places the icon bar above the AddOns window instead of below it.',
    ['Tip.AddOns.BottomListIconOnly']= 'Only includes addons that have their own icon in the bar.',
    ['Tip.AddOns.RightList']= 'Shows your saved profiles (sets of enabled addons) to the right of the AddOns window so you can load them with one click.',
    ['Tip.AddOns.RightListClear']= 'Deletes all saved addon profiles, after asking for confirmation.',
    ['Tip.AddOns.InfoPlus']= 'Adds to each list row a checkbox to mark it as a shortcut, its index number and the memory usage in the tooltip. It also adds a button next to "Disable All" to keep WoWToolsPlus and BugSack enabled.',
    ['Tip.AddOns.LoadProfile']= 'Enables the addons in this profile, disables the rest for the selected character and reloads the UI.',
    ['Tip.AddOns.ReplaceProfile']= 'Overwrites this profile with the currently enabled addons, after asking for confirmation.',
    ['Tip.Faction.Enable']= 'Improves the Reputation window: more detailed standings and progress, an on-screen reputation tracking button, extended reputation chat messages and a faction list in the Renown window.',
    ['Tip.Faction.Track']= 'Shows a movable on-screen button with the list of reputations still in progress (or with a pending paragon reward).',
    ['Tip.Faction.TrackAutoHide']= 'Automatically hides the reputation tracker in combat, in dungeons and raids, in pet battles and in vehicles.',
    ['Tip.Faction.TrackSelected']= 'Only shows the factions you mark in the tracker. When on, a checkbox appears on each row of the Reputation window to choose them.',
    ['Tip.Faction.ChatGain']= 'Extends reputation gain chat messages with the faction\'s icon, current standing and progress.',
    ['Tip.Faction.UIPlus']= 'In the Reputation window, colors the bars by standing and shows icons and more detailed standing and progress text.',
    ['Tip.Faction.TrackShowList']= 'Shows the list with each reputation\'s standing and progress next to the tracking button.',
    ['Tip.Faction.TrackTextRight']= 'Places each reputation\'s text to the right of its icon instead of the left.',
    ['Tip.Faction.TrackGrowUp']= 'Makes the list grow upward from the button instead of downward.',
    ['Tip.Faction.TrackShowName']= 'Shows each faction\'s name. If turned off, only icons are shown, and only for factions that have an icon.',
    ['Tip.Faction.TrackRenownOnly']= 'Only shows renown factions (major factions) in the tracker.',
    ['Tip.Faction.RenownList']= 'Shows buttons for all major factions with their renown level next to the Renown window; click one to open that faction.',
    ['Tip.Faction.RenownUnlockedOnly']= 'Only shows major factions you have already unlocked in the list.',
    ['Tip.Attributes.Reset']= 'Recalculates the stat list for your current specialization and reapplies the configured colors.',
    ['Tip.Attributes.Show']= 'Shows or hides the stats panel next to the button. The button itself stays visible.',
    ['Tip.Attributes.SendMessage']= 'Sends your specialization and stats to chat: whispers your target if it is another player, otherwise sends to raid, party or say. If a chat box is open, it only inserts the text.',
    ['Tip.Macro.Module']= 'Enhances the macro window: lists to insert spells, equipment, emotes and common macros, favorite macros, notes and alternative window layouts.',
    ['Tip.Macro.Note']= 'Opens a text window to write macro notes. Notes are saved per character.',
    ['Tip.Macro.LayoutLeft']= 'Moves the macro icon list outside the window on the left and shows the notes box inside the window. Cannot be changed in combat.',
    ['Tip.Macro.LayoutRight']= 'Moves the macro icon list outside the window on the right and shows the notes box inside the window. Cannot be changed in combat.',
    ['Tip.Macro.LayoutDefault']= 'Uses Blizzard\'s default layout: macro list at the top, macro text below.',
    ['Tip.Macro.LayoutSplit']= 'Puts the macro list on the left half of the window and the macro text on the right half. Cannot be changed in combat.',
    ['Tip.Macro.ButtonPlus']= 'Shows the extra buttons in the macro window: spell, equipment, emote and common macro lists, the new empty macro and favorites buttons, and the buttons that insert Target and Attack commands.',
    ['Tip.Macro.DeleteGeneral']= 'Deletes all general macros (after confirmation). This cannot be undone and does not work in combat.',
    ['Tip.Macro.DeleteCharacter']= 'Deletes all character-specific macros of this character (after confirmation). This cannot be undone and does not work in combat.',
    ['Tip.Macro.Favorite']= 'Saves the selected macro (name, icon and text) to favorites so you can create new macros from it later. Click again to remove it.',
    ['Tip.Macro.FavoriteRemove']= 'Removes this macro from favorites and prints its text in chat so you can restore it if needed.',
    ['Tip.Macro.Preset']= 'Creates a new macro with this text.',
    ['Tip.Macro.SelectIcon']= 'Changes the selected macro\'s icon to this spell or item icon (taken from the macro text). Unsaved macro text is saved first. Does not work in combat.',
    ['Tip.Macro.FindSpell']= 'Opens the spellbook at this spell.',
    ['Tip.House.Module']= 'Enhances the housing decor catalog: shows placed/owned counts, placement cost, indoor/outdoor use, first-acquisition XP bonus, a tracking button, the list count, and source and tags in the preview.',
    ['Tip.Objective.Module']= 'Enhances the objective tracker: "stop tracking all" buttons per section, a menu (collapse/expand, scale, opacity), larger quest item buttons, scenario stage count and more.',
    ['Tip.Objective.CollapseAll']= 'Collapses every visible section of the tracker (not the whole tracker). You can also use the mouse wheel on the header.',
    ['Tip.Objective.ExpandAll']= 'Expands every visible section of the tracker. You can also use the mouse wheel on the header.',
    ['Tip.Objective.AutoCombat']= 'Automatically collapses the whole tracker when you enter combat and expands it when combat ends. Requires "Auto" to be enabled.',
    ['Tip.Objective.AutoCollapse']= 'Automatically collapses quest, achievement and other sections when you enter an instance (or start a keystone) and expands them outside. It also restores the tracker\'s last collapsed state.',
    ['Tip.Objective.ClearAll']= 'Stops tracking all quests, world quests, campaign quests, achievements, profession recipes, Traveler\'s Log activities, collections and neighborhood initiatives (after confirmation).',
    ['Tip.MainMenu.Enable']= 'Shows info on the micro menu buttons (item level, durability, quest count, online guild members, FPS/latency, gold, etc.) and adds details to their tooltips.',
    ['Tip.MainMenu.FontSize']= 'Sets the size of the info text shown on the micro menu buttons.',
    ['Tip.MainMenu.Alpha']= 'Micro menu and bag buttons are shown at the set opacity when the mouse is not over them, and fully when it is. Toggling requires a UI reload.',
    ['Tip.MainMenu.FrameratePlus']= 'Adds a small button to the FPS display: right-drag to move it (the position is saved) and use the mouse wheel to change the font size.',
    ['Tip.MainMenu.FramerateLogIn']= 'Automatically shows the FPS display when you log in.',
    ['Tip.Friends.Enable']= 'Enhances the Friends list: shows character details (level, class, zone) in the friends, Battle.net, Who and Quick Join lists, and improves the raid info panels.\nRequires a reload.',
    ['Tip.Friends.StatusAvailable']= 'Each time you log in with this character, automatically sets your Battle.net status to Available (clears Away/Busy). Click again to turn off.',
    ['Tip.Friends.StatusAway']= 'Each time you log in with this character, automatically sets your Battle.net status to Away. Click again to turn off.',
    ['Tip.Friends.StatusDND']= 'Each time you log in with this character, automatically sets your Battle.net status to Busy. Click again to turn off.',
    ['Tip.Friends.OtherCharStatus']= 'Battle.net status automatically set when this character logs in. Uncheck to remove the setting.',
    ['Tip.Friends.BNetInfo']= 'Prints a chat message (name, status, level, character and zone) whenever a Battle.net friend\'s online status, character or location changes.',
    ['Tip.Friends.WoWOnly']= 'Only reports Battle.net friends playing this version of WoW in your region; uncheck to also report friends in other games or versions.',
    ['Tip.Friends.FavoriteOnly']= 'Only reports Battle.net friends marked as favorites.',
    ['Tip.Friends.NoCombat']= 'Suppresses friend notifications while in combat inside an instance.',
    ['Tip.Friends.FriendPlus']= 'Shows extra details on each Friends list row: character name, level, class color, zone, Battle.net note, and whether they are in another region or version.',
    ['Tip.PetBattle.Enable']= 'Enhances pet battles: adds pet ability panels, a pet family strength/weakness bar and a click-to-move button (each can be toggled below).',
    ['Tip.PetBattle.AbilityButton']= 'During pet battles, shows a panel next to enemy pets and your reserve pets with their abilities (cooldowns, strong/weak hints), health, quality, level, auras and stats. Also adds strong/weak type hints to your own ability bar.',
    ['Tip.PetBattle.TypeButton']= 'Shows a row of pet family icons with the families each one is strong and weak against. Clicking an icon opens the Pet Journal filtered by that family. Appears automatically with the Pet Journal open or during pet battles.',
    ['Tip.PetBattle.ClickMoveButton']= 'Adds a button by the player portrait: left-click toggles Click-to-Move, right-click opens a menu where you can lock Click-to-Move and camera follow styles so they are restored automatically if changed (out of combat).',
    ['Tip.PetBattle.AbilityShow']= 'Shows or hides this pet\'s ability panel (you can also left-click this button).',
    ['Tip.PetBattle.AbilityName']= 'Shows the pet\'s name on the panel.',
    ['Tip.PetBattle.Ability3D']= 'Shows the pet\'s 3D model on the panel. Use the mouse wheel over the model to zoom.',
    ['Tip.PetBattle.OpenJournalAfter']= 'Automatically opens the Pet Journal when a pet battle ends (only out of combat and when Revive Battle Pets is not on cooldown).',
    ['Tip.PetBattle.TypeShow']= 'Shows or hides the pet family icon bar (you can also left-click this button).',
    ['Tip.PetBattle.TypeAlwaysShow']= 'Keeps the pet family bar visible at all times out of combat, not only with the Pet Journal or in pet battles.',
    ['Tip.PetBattle.ClickToMove']= 'Toggles Click-to-Move (right-click the ground to walk there). Cannot be changed in combat. Toggling it manually removes the lock.',
    ['Tip.PetBattle.LockClickMoveOn']= 'Locks Click-to-Move on: if another addon or setting turns it off, it is turned back on automatically out of combat.',
    ['Tip.PetBattle.LockClickMoveOff']= 'Locks Click-to-Move off: if another addon or setting turns it on, it is turned back off automatically out of combat.',
    ['Tip.PetBattle.AutoClickMoveLevel']= 'Locks Click-to-Move based on your level: off below max level, on at max level.',
    ['Tip.PetBattle.LockCamera']= 'Locks this camera style: if it gets changed, it is restored automatically out of combat.',
    ['Tip.PetBattle.ClickMoveUIParent']= 'Detaches the button from the player frame so you can place it anywhere (Alt+right-drag to move). Unchecked, it stays anchored under the player portrait.',
    ['Tip.Currency.Enable']= 'Enhances the Currency window: shows earned percentage and warband totals, adds a search box and expand/collapse all buttons, provides an on-screen currency tracking button and warns when a currency is capped.\nRequires a reload.',
    ['Tip.Currency.Track']= 'Shows an on-screen button that lists your currencies (and tracked items) with their amounts. Left-click opens the Currency window, right-click opens the menu, Alt+right-drag moves it.',
    ['Tip.Currency.CapWarning']= 'Automatically posts a chat message when a currency reaches its total or weekly cap.',
    ['Tip.Currency.Plus']= 'Adds earned percentage, warband totals and transferable/warband icons to the currency list, extra info to the currency popup, plus a search box and expand/collapse all buttons.',
    ['Tip.Currency.ShowList']= 'Shows or hides the currency list next to the button (you can also use the mouse wheel over the button).',
    ['Tip.Currency.AutoHide']= 'Automatically hides the tracking button in instances, in combat, during pet battles and while in a vehicle.',
    ['Tip.Currency.OnlySelected']= 'Only tracks the currencies checked here (you can also check them in the Currency window); when off, shows every currency you have more than 0 of.',
    ['Tip.Currency.AddByID']= 'Enter a currency ID to add it to the tracked list.',
    ['Tip.Currency.TrackItems']= 'Also lists the tracked items you have in your bags. Drag an item onto the tracking button to add or remove it.',
    ['Tip.Currency.UseItem']= 'Turns the listed items into buttons you can click to use them. When enabled, items are not listed during combat.',
    ['Tip.Currency.ShowName']= 'Shows the currency or item name in the list, besides the icon and amount.',
    ['Tip.Currency.TextRight']= 'Places the amount text to the right of the icons (unchecked: to the left).',
    ['Tip.Currency.GrowUp']= 'Makes the list grow upward from the button (unchecked: downward).',
    ['Tip.Gem.Enable']= 'Shows the usable gems from your bags next to the Socket Gems window; left-click one to pick it up and place it in a socket. Remembers which gem you used in each equipment slot and can add an Extract Gem spell button.',
    ['Tip.Gem.Favorite']= 'Marks this gem as a favorite so it is listed first.',
    ['Tip.Gem.PlaceLeft']= 'Moves this gem to the left column of the window (shortcut: Alt+left-click). Click again to return it to the main list.',
    ['Tip.Gem.PlaceTop']= 'Moves this gem to the top row of the window (shortcut: Alt+mouse wheel). Click again to return it to the main list.',
    ['Tip.Gem.PlaceRight']= 'Moves this gem to the right column of the window (shortcut: Alt+right-click). Click again to return it to the main list.',
    ['Tip.Gem.Show']= 'Shows or hides the gem buttons around the Socket Gems window (you can also left-click this button; mouse wheel changes the scale). Cannot be changed in combat.',
    ['Tip.Gem.SpellButton']= 'Adds an Extract Gem spell button to the bottom-left corner of the Socket Gems window.\nRequires a reload.',
    ['Tip.Gem.ClearColumn']= 'Moves all gems in that column back to the main list.',
    ['Tip.Gem.ClearRecord']= 'Clears the gems recorded for each equipment slot for this class (used to show the previously used gem next to each socket).',
    ['Tip.Professions.Enable']= 'Enhances profession windows: adds quick profession buttons next to the Professions window, shows how many of the crafted item you own and recipe tooltips, adds a "Learn all" button at trainers and improves Archaeology (dig site progress bar, sound alert).',
    ['Tip.Professions.QuickButtons']= 'Shows buttons for all your professions (including Fishing, Cooking and Archaeology) at the bottom-right of the Professions window; click one to open that profession.',
    ['Tip.Professions.CookingFire']= 'Adds a button next to the Cooking button that casts Cooking Fire.',
    ['Tip.Professions.AutoDigBar']= 'Automatically shows the Archaeology dig site progress bar when you stop moving inside a dig site (not in instances).',
    ['Tip.Panel.ResetSettings']= 'After confirmation, erases all settings of every module of the addon, restoring defaults, and reloads the UI.',
    ['Tip.Panel.ClearInput']= 'After confirmation, erases the data you entered and saved in the addon (custom item lists, texts, etc.) and reloads the UI.',
    ['Tip.Panel.ClearWarband']= 'After confirmation, erases the cached Warband data of all characters (level, item level, specialization, items, currencies…) and reloads the UI.',
    ['Tip.Panel.WarbandItems']= 'Opens a window listing the items and currencies recorded for all your characters.',
    ['Tip.Panel.ClearAll']= 'After confirmation, erases everything at once: addon settings, input data and Warband data, then reloads the UI.',
    ['Tip.Panel.Realm']= 'Shows the region/language of other players\' realms (e.g. DE, FR, GB) next to their names. Requires /reload.',
    ['Tip.Talking.Hide']= 'Automatically closes the talking head frame (NPC story dialogue) but still plays its voice line.',
    ['Tip.Talking.Print']= 'Shows the NPC name and text of the hidden dialogue in the chat.',
    ['Tip.DELETE.Option']= 'Automatically fills in the confirmation word in popups that ask for it (e.g. "DELETE" when destroying an item, unlearning a profession…); you only have to click Accept.',
    ['Tip.HelpTip.Option']= 'Automatically hides the game tutorial tips and new player pointer arrows, disables the new player tutorials (CVar showNPETutorials), and hides the new features splash screen and the thank-you window after reporting.',
    ['Tip.Achievement.Option']= 'Enhances the achievements window: shows achievement ID, progress of pending criteria, reward icon and whether this character earned it, adds completion progress to categories and remembers the filter; also adds an instance achievements list button to the achievements window and the Adventure Guide.',
    ['Tip.Brewfest.Option']= 'During the Brewfest ram racing, shows a button with fatigue stacks, speed, remaining time and the Brewfest tokens earned, and shows an icon with a sound when you carry a Portable Brewfest Keg. Shift+Left click creates a "/click ExtraActionButton1" macro.',
    ['Tip.Scrapping.ExcludeItem']= 'When checked, this item is never added automatically to the scrapper by the Add buttons.',
    ['Tip.Scrapping.ClearExcluded']= 'After confirmation, empties the list of items excluded from auto-adding.',
    ['Tip.Scrapping.Option']= 'Adds buttons to the scrapper window: add scrappable gems, equipment or all items from your bags in one click (up to 9, skipping excluded items), and clear all; slots show item info. Not available in combat.',
    ['Tip.Marker.HotKey']= 'Shows the bound key bindings on the ping, countdown and raid target buttons.',
    ['Tip.Marker.Tooltip']= 'Shows tooltips when hovering over the toolbar buttons.',
    ['Tip.Marker.TooltipLeft']= 'Shows the button tooltips on the left side of the toolbar instead of the right.',
    ['Tip.Marker.Option']= 'Shows a movable toolbar with buttons for pings, countdown, ready check, role check, raid target icons and world markers.',
    ['Tip.Marker.Reset']= 'After confirmation, erases all settings of the raid marker tool (position, scale, etc.) and reloads the UI.',
    ['Tip.Menu.Scale']= 'Changes the size of this frame or button (0.4 - 4). Protected frames cannot be changed in combat.',
    ['Tip.Menu.Strata']= 'Changes the frame strata (drawing layer): higher layers are drawn on top of other windows. MEDIUM is the usual value.',
    ['Tip.Menu.StrataLevel']= 'Puts the frame on this layer. The lower in the list, the higher it is drawn.',
    ['Tip.Menu.BgAlpha']= 'Changes the background opacity (0 = transparent, 1 = opaque).',
    ['Tip.Menu.RestData']= 'After confirmation, erases all saved data and settings of this module and reloads the UI.',
    ['Tip.Menu.ToTop']= 'Changes the layout of the buttons so they extend upwards.',
    ['Tip.Menu.CVar']= 'Turns the game setting on or off (CVar: %s). Cannot be changed in combat.',
    ['Tip.Menu.ClearAll']= 'After confirmation, removes all entries from this list.',
    ['Tip.Key.SetKey']= 'Opens a box to type the key binding used by this button (e.g. Q, ALT-Q, BUTTON5). Cannot be changed in combat.',
    ['Tip.Menu.Difficulty']= 'Changes the dungeon or raid difficulty for the next instances you enter. Only the group leader (or when solo) can change it.',
    ['Tip.Menu.LootSpec']= 'Chooses the specialization your loot is generated for (loot specialization).',
    ['Tip.Menu.Spec']= 'Click to switch to this specialization. Cannot be done in combat. The submenu chooses the loot specialization.',
    ['Tip.Menu.WarMode']= 'Shows whether War Mode is on. Click to open the PvP talents window to change it.',
    ['Tip.WoWList.ClearCharacter']= 'After confirmation, deletes all Warband data recorded for this character. If it is your current character, the UI is reloaded.',
    ['Tip.WoWList.ClearCharacterType']= 'After confirmation, deletes only the recorded data of this type for this character.',
    ['Tip.WoWList.ClearTypeAll']= 'After confirmation, deletes the recorded data of this type for all characters.',
    ['Tip.WoWList.ClearRegion']= 'After confirmation, deletes all data of characters from other regions (not the current one).',
    ['Tip.WoWList.ClearBattleTag']= 'After confirmation, deletes all data of characters that belong to other Battle.net accounts.',
    ['Tip.WoWList.Me']= 'Clears the search and jumps to and selects your current character in the list.',
    ['Tip.WoWList.Keystone']= 'Filters the list to show only characters that have a Mythic Keystone.',
    ['Tip.WoWList.Filter']= 'Filters the list to show only characters that match this entry.',
    ['Tip.Bag.Option']= 'Enhances the bags: adds a Warband items list button, a button to quickly destroy low-quality items, configurable columns per bag, and sorting and assignment options in the bag menu.',
    ['Tip.Bag.Columns']= 'Lets you choose the number of columns of each bag and of the combined bag.',
    ['Tip.Bag.ColumnsValue']= 'Sets this number of columns for this bag. It does not refresh in combat.',
    ['Tip.Bag.ColumnsReset']= 'Restores the default number of columns in all bags.',
    ['Tip.Bag.DeleteButton']= 'Adds a button to the bags to quickly destroy low-quality items from a list (poor, common, uncommon, heirloom).',
