    ['Tip.Invite.DeclineResting']= 'While in a rest area (cities, inns), automatically declines group invites from non-friends after 3 seconds.',
    ['Tip.Invite.Test']= 'Shows a test group invite dialog so you can see how it works.',
    ['Tip.Invite.Summon']= 'Automatically accepts summons after 3 seconds. Cancelled in combat or by holding a modifier key.',
    ['Tip.Invite.RestingTips']= 'Shows a chat notice when you enter or leave a rest area (only you see it).',
    ['Tip.Invite.Focus']= 'Modifier + left-click on a unit frame or the unit under the mouse sets it as focus; modifier + right-click clears the focus. Requires a reload.',
    ['Tip.Invite.FocusKey']= 'Chooses the modifier key used to set the focus.',
    ['Tip.Invite.DeclineList']= 'Group invites from these players are declined automatically (the number is how many times). Click a player to remove them from the list.',
    ['Tip.LFD.RolePvE']= 'Sets the role used when queuing in the Dungeon and Raid Finder.',
    ['Tip.LFD.RolePvP']= 'Sets the role used when queuing for battlegrounds.',
    ['Tip.LFD.AutoRole']= 'Automatically sets your PvE and PvP queue roles to match your current specialization on login and when you change spec. When off, roles are only set if none is selected.',
    ['Tip.LFD.LeaveInstance']= 'After finishing a random dungeon, shows a countdown and leaves automatically (30 s, or the "Auto confirm" seconds after looting if auto roll is on); leaves islands at once and battlegrounds after the set seconds. Hold a modifier key to cancel.',
    ['Tip.LFD.QueueInfo']= 'Shows a list with your current queue information (queues, premade group applications, etc.) next to the button.',
    ['Tip.LFD.LFGPlus']= 'Improves Premade Groups: listings show the leader\'s Mythic+/PvP rating, friends in the group, realm region and class/role icons; double-click an entry to sign up; adds a button with more activities. Disabling requires a reload.',
    ['Tip.LFD.RoleCheck']= 'On role checks, automatically picks the role of your current specialization and accepts after the "Auto confirm" seconds. Hold a modifier key to cancel.',
    ['Tip.LFD.ReleaseRes']= 'In battlegrounds and other PvP areas, automatically releases your spirit when you die and queues for the spirit healer resurrection. It does not release if you have a soulstone or other self-resurrect, or while holding a modifier key.',
    ['Tip.LFD.ReleaseResAll']= 'Also releases automatically in the open world (or when not grouped) and resurrects automatically when you reach your corpse. Hold Alt to cancel.',
    ['Tip.LFD.HideLocked']= 'Hides the instances you cannot queue for from the menu lists.',
    ['Tip.LFD.CompleteEntry']= 'Recorded number of completions. Uncheck to delete this entry.',
    ['Tip.LFD.AutoConfirmSec']= 'Seconds to wait before automatic actions: accepting role checks, leaving battlegrounds and leaving the dungeon after looting.',
    ['Tip.LFD.AutoRoll']= 'Rolls on group loot automatically: Need for item level upgrades and uncollected pets, mounts, toys and housing decor; Transmog for uncollected appearances; Greed for consumables and other cases. Anything else is left for you to decide.',
    ['Tip.LFD.ConfirmBoP']= 'Automatically confirms the "Bind on Pickup" warning when you roll on such items.',
    ['Tip.LFD.LootPlus']= 'Improves the loot history window: shows item subtype and stats and adds a button to whisper the winner asking for the item.',
    ['Tip.Guild.ShowList']= 'Shows the guild member list (name, level, zone, notes) at the bottom of this menu. Click a member to whisper them.',
    ['Tip.Guild.ShowOffline']= 'Also lists offline members in the member list.',
    ['Tip.Guild.GuildInfo']= 'Runs /guildinfo automatically on login (shows the guild creation date and member count in chat) and saves the result to show it in this tooltip.',
    ['Tip.Guild.Truncate']= 'Shortens the guild name shown in the menu to this number of characters.',
    ['Tip.Group.ChatType']= 'Sets the button\'s chat channel (party, raid, instance, raid warning) and opens the chat box on it. Afterwards, left-clicking the button chats in this channel.',
    ['Tip.Group.MembersHP']= 'When you hover the button, its tooltip shows the group members\' health and other info.',
    ['Tip.Group.ChatBubbles']= 'Turns chat bubbles for party chat on or off (game setting). Cannot be changed in combat.',
    ['Tip.Group.ReadyShow']= 'Shows the ready check window on your screen (does not start a ready check for the group).',
    ['Tip.Group.AutoReady']= 'When a ready check starts, automatically answers "Ready" or "Not ready" after a few seconds; "Manual" leaves it to you. Hold Alt to cancel.',
    ['Tip.Group.WheelSend']= 'Sends this custom message to the group chat now (visible to other players).',
    ['Tip.Group.WheelEdit']= 'Edits the custom message sent with the mouse wheel. %s is replaced with your group number.',
    ['Tip.LFD.ShowReadyPopup']= 'Shows or hides the "dungeon ready" window (the enter-instance prompt), useful to reopen it after closing it.',
    ['Tip.WorldMap.Enable']= 'Adds world map improvements: map ID, coordinates, names on points of interest, dungeons and flight points, rewards on world quests and your own map pins.',
    ['Tip.WorldMap.Title']= 'Shows or hides the title text of the map window (Map & Quest Log / World Map).',
    ['Tip.WorldMap.MapID']= 'Shows on the map its uiMapID, map group, active event icons, number of quests on the map, your current layer and the zone story achievement.',
    ['Tip.WorldMap.MapXY']= 'Shows the cursor coordinates next to the map title and a box with your coordinates. Type coordinates and press Enter to place a waypoint; left-click the icon to insert your position in chat, and the mouse wheel returns to the current map.',
    ['Tip.WorldMap.PlayerXY']= 'Shows an on-screen button with your coordinates in real time, even while the map is closed. Alt+drag to move it.',
    ['Tip.WorldMap.SharePos']= 'Inserts your current position into the chat box (as a waypoint link when the map allows it, otherwise as coordinates). It is not sent automatically.',
    ['Tip.WorldMap.CopyPos']= 'Opens a window with your current coordinates so you can copy them.',
    ['Tip.WorldMap.PlayerXYRight']= 'Places the coordinates text to the right of the button; uncheck to place it on the left.',
    ['Tip.WorldMap.PlayerXYReset']= 'Resets all settings of the player coordinates button (position, scale, background, etc.).',
    ['Tip.WorldMap.AreaPOIName']= 'Shows under the map points of interest (events, special areas) their name or remaining time. In the submenu you can hide or rename each one.',
    ['Tip.WorldMap.AreaPOIItem']= 'Shows or hides the text of this point of interest on the map.',
    ['Tip.WorldMap.AreaPOIRename']= 'Sets a custom name for this point of interest. In the dialog, Alt restores the original name.',
    ['Tip.WorldMap.AreaPOIClear']= 'Deletes all custom names and shows again every hidden point of interest.',
    ['Tip.WorldMap.DungeonName']= 'Shows the names of dungeon, raid and delve entrances on the map, and adds their IDs to the tooltip (Alt: description).',
    ['Tip.WorldMap.WorldQuestReward']= 'Replaces the world quest icon with its reward icon and shows below the item level, currency amount, or whether it upgrades your gear or is an uncollected appearance.',
    ['Tip.WorldMap.PlayerPin']= 'Enables your own map pins: named points with an icon that you create and edit, which can show only for certain classes, professions, quests or achievements. Click one to set a waypoint on it.',
    ['Tip.WorldMap.PinEditUI']= 'Opens the map pin editor to create, modify, import or export pins.',
    ['Tip.WorldMap.PinButtonParent']= 'Places the pins button next to the world map menu button; when unchecked, it is placed next to the minimap tracking button.',
    ['Tip.WorldMap.PinExport']= 'Generates a text with all pins of this map so you can copy and share it.',
    ['Tip.WorldMap.PinProfession']= 'The pin is only shown to characters who know one of the checked professions.',
    ['Tip.WorldMap.PinClass']= 'The pin is only shown to characters of the checked classes.',
    ['Tip.WorldMap.PinCriteria']= 'Links the pin to this achievement criterion: it is hidden once the criterion is completed.',
    ['Tip.WorldMap.Plus']= 'Extra map improvements: activity tracker settings (scale, transparency, reputation text), campaign IDs in the tooltip and buttons to collapse or expand all quest log headers.',
    ['Tip.WorldMap.AbandonQuests']= 'Abandons at once all quests of one type in the log (daily, weekly, campaign, completed, low level…). Always asks for confirmation.',
    ['Tip.WorldMap.AbandonType']= 'Abandons every abandonable quest of this type, after confirming.',
    ['Tip.WorldMap.FlightMapName']= 'Shows the name of each flight point on the flight map.',
    ['Tip.Gossip.Module']= 'Adds two buttons: a gossip one that automatically picks NPC dialogue options, and a quest one that automatically accepts and turns in quests. It also includes skipping movies and cinematics, replacing dialogue texts and text to speech.',
    ['Tip.Gossip.Enable']= 'Automatically picks NPC dialogue options: the ones you checked, quest-related ones and some inside instances; it also closes dialogues with no options. Hold a modifier key (Alt, Ctrl or Shift) while talking to pause it.',
    ['Tip.Gossip.UniqueChoice']= 'If a player choice window has only one option, it picks it automatically.',
    ['Tip.Gossip.CustomList']= 'Dialogue options that are always picked automatically. Add them with the checkbox shown next to each option in the gossip window.',
    ['Tip.Gossip.CustomItem']= 'When checked, this dialogue option is picked automatically when talking to the NPC.',
    ['Tip.Gossip.ReplaceText']= 'Replaces the text, icon and color of dialogue options with the ones you defined or with the addon defaults.',
    ['Tip.Gossip.ReplaceEdit']= 'Opens the window to edit the text, icon and color of dialogue options.',
    ['Tip.Gossip.ReplaceDefault']= 'Also uses the addon\'s built-in list of replacements, in addition to yours.',
    ['Tip.Gossip.DisableNPC']= 'NPCs for which dialogue options are not picked and quests are not accepted or turned in automatically. Add them with the checkbox in the gossip or quest window.',
    ['Tip.Gossip.DisableNPCItem']= 'When checked, the dialogue and quest automations do not act on this NPC.',
    ['Tip.Gossip.Choice']= 'Player choice options that are picked automatically (add them with the checkbox under each option). If several apply, the one with the highest rarity is chosen.',
    ['Tip.Gossip.EditAddAll']= 'Adds to your list every option of the current dialogue that is not already in it, so you can edit its text.',
    ['Tip.Gossip.SkipMovie']= 'Automatically skips movies you have already seen; the first time they play and are saved to the list. Hold a modifier key to watch it.',
    ['Tip.Gossip.Subtitles']= 'Shows subtitles in movies and cinematics (CVar movieSubtitle). Cannot be changed in combat.',
    ['Tip.Gossip.SkipCinematic']= 'Automatically cancels in-game cinematics. It does not act in combat or while holding a modifier key.',
    ['Tip.Gossip.CinematicInstance']= 'When checked, cinematics are not skipped inside instances (dungeons, raids, scenarios…).',
    ['Tip.Gossip.MovieList']= 'List of game movies; click one to play it. If it is not downloaded, its submenu lets you download it.',
    ['Tip.Gossip.MovieClear']= 'Clears the list of already seen movies; next time they will play again instead of being skipped.',
    ['Tip.Gossip.QuestEnable']= 'Automatically accepts and turns in quests and picks quests in the NPC dialogue. Hold a modifier key to pause it; Alt on the button disables it temporarily.',
    ['Tip.Gossip.QuestTrivial']= 'Turns minimap tracking of low-level quests on or off. When off, those quests are not accepted automatically.',
    ['Tip.Gossip.QuestReward']= 'When turning in a quest with several rewards, picks one: first an upgrade to your gear, then an uncollected appearance, otherwise the highest sell price. Ignores epics, cosmetics, mounts and set items. Remembers your manual choice for each quest.',
    ['Tip.Gossip.QuestCustom']= 'Quests that are always picked automatically in the NPC dialogue, even when that NPC is disabled. Add them with the checkbox in the quest window.',
    ['Tip.Gossip.QuestShare']= 'Automatically shares shareable quests with your group, when you accept them and when the group changes. Only in a group.',
    ['Tip.Gossip.QuestNum']= 'Shows on the quest button how many quests you have (normal, daily, weekly, campaign…). Hidden inside instances.',
    ['Tip.Gossip.AutoQuestWatch']= 'Automatically tracks quests when you accept or progress them (CVar autoQuestWatch). Cannot be changed in combat.',
    ['Tip.Gossip.TTS']= 'Automatically reads aloud the text of quests and NPC dialogues when they open (each text only once).',
    ['Tip.Challenge.Module']= 'Adds improvements to the Mythic+ tab of the Group Finder: per-dungeon info, teleport portals, Great Vault, your characters\' keystones, affixes and a button to announce your keystone when a dungeon ends.',
    ['Tip.Challenge.DungeonInfo']= 'Shows on each dungeon of the Mythic+ tab its name, timed/total runs, your score and a mark if your keystone is for that dungeon.',
    ['Tip.Challenge.Portals']= 'Shows a button with each dungeon\'s teleport spell so you can cast it with one click (dimmed if you don\'t know it). Cannot be changed in combat.',
    ['Tip.Challenge.Vault']= 'Shows this week\'s Great Vault progress in the top-left corner.',
    ['Tip.Challenge.VaultPvP']= 'Also includes PvP progress in the Great Vault panel.',
    ['Tip.Challenge.Guild']= 'Shows your guild\'s best Mythic+ run this week (dungeon, level and members).',
    ['Tip.Challenge.Affix']= 'Shows the season\'s affix schedule in the bottom-right corner and marks the current week.',
    ['Tip.Challenge.RightInfo']= 'Shows on the right your run history, this week\'s runs per dungeon and the weekly loot item level by key level.',
    ['Tip.Challenge.KeystonePlus']= 'Adds party info (ready check, location, item level) to the keystone window, plus buttons to insert/remove and link the keystone.',
    ['Tip.Challenge.EndSay']= 'When a Mythic+ dungeon ends, shows a button with your new keystone to announce it in chat.',
    ['Tip.Challenge.AlwaysShow']= 'Shows the keystone button when you log in, not only after finishing a dungeon.',
    ['Tip.Challenge.Say']= 'Sends your custom text and your keystone link to instance, raid or party chat.',
    ['Tip.Challenge.SayEdit']= 'Edits the text sent before the keystone link.',
    ['Tip.Challenge.SayTarget']= 'Whispers your text and keystone link to your friendly player target.',
    ['Tip.Challenge.SayParty']= 'Sends your text and keystone link to party chat.',
    ['Tip.Challenge.SayRaid']= 'Sends your text and keystone link to raid chat.',
    ['Tip.Challenge.SayGuild']= 'Sends your text and keystone link to guild chat.',
    ['Tip.Challenge.SendKey']= 'Sends only your keystone link to group chat (no text).',
    ['Tip.Challenge.LinkKey']= 'Inserts your keystone link into the chat box without sending it.',
    ['Tip.Challenge.SendScore']= 'Sends your Mythic+ score link to group chat.',
    ['Tip.PaperDoll.Module']= 'Improves the character and inspect windows: info on each slot, stats with decimals, equipment sets, realm, level and side tabs.',
    ['Tip.PaperDoll.Slots']= 'Shows extra info on each equipped slot (also when inspecting): item level, stats, gems, enchant, upgrade, durability and PvP items. Dims pieces that are not your preferred armor type.',
    ['Tip.PaperDoll.EquipSetButton']= 'Shows a floating button with your Equipment Manager sets to switch sets with one click.',
    ['Tip.PaperDoll.EquipSetPlus']= 'Adds the number of pieces of each set to the Equipment Manager and a button to create an empty set.',
    ['Tip.PaperDoll.Stats']= 'Lets you choose which stats appear in the character panel and when they are shown (by role, primary stat or value), from a menu button next to the close button.',
    ['Tip.PaperDoll.StatDecimals']= 'Shows secondary stats with their rating, the bonus percentage and the chosen decimals, as in the example.',
    ['Tip.PaperDoll.DecimalsCount']= 'Number of decimals used for stat percentages.',
    ['Tip.PaperDoll.Realm']= 'Shows your realm name (and how many are connected) at the top of the character window, plus a WoW Token button that opens the Warband item list.',
    ['Tip.PaperDoll.Level']= 'Changes the character level text and adds a button with character data, Chromie Time, spec role, War Mode and total durability.',
    ['Tip.PaperDoll.Flyout']= 'Improves the item flyout of each slot: shows item level, comparison with the equipped item and upgrade level. Includes its scale.',
    ['Tip.PaperDoll.Tabs']= 'Adds info to the side tabs: PvE/PvP item level, titles collected and the current equipment set.',
    ['Tip.PaperDoll.SetToRight']= 'Places the set buttons in a row to the right instead of a column.',
    ['Tip.PaperDoll.SetItemLevel']= 'Shows your average equipped item level on the button.',
    ['Tip.PaperDoll.SetNumItems']= 'Shows how many pieces each set has (in red if any are missing).',
    ['Tip.PaperDoll.SetSecure']= 'Uses secure buttons so you can switch sets (weapons) in combat.',
    ['Tip.PaperDoll.SetResetAll']= 'Resets all options of the sets button (asks for confirmation).',
    ['Tip.PaperDoll.StatItem']= 'Adds or removes this stat from the character panel. The submenu lets you hide it by value, role or primary stat.',
    ['Tip.PaperDoll.StatHideAt']= 'Hides this stat when its value equals the one shown.',
    ['Tip.PaperDoll.StatRole']= 'Shows this stat only when your specialization has this role.',
    ['Tip.PaperDoll.StatPrimary']= 'Shows this stat only if your primary stat is the one shown.',
    ['Tip.PaperDoll.StatClear']= 'Removes all stats from the character panel (asks for confirmation).',
    ['Tip.PaperDoll.StatRevert']= 'Restores the game\'s default stat list (asks for confirmation).',
    ['Tip.MiniMap.Module']= 'Improves the minimap: a button that collects addon icons, tracking of events and world quests, auto zoom, instance difficulty, clock and stopwatch. Disabling it requires a reload.',
    ['Tip.MiniMap.Townsfolk']= 'Toggles the minimapTrackingShowAll CVar to show every townsfolk tracking option in the tracking menu. Cannot be changed in combat.',
    ['Tip.MiniMap.TrackButton']= 'Shows a button with a text list of nearby points of interest, world quests and rare events (vignettes). Only outside instances (or in delves).',
    ['Tip.MiniMap.ZoomInfo']= 'Shows the current zoom level and view radius in yards on the minimap.',
    ['Tip.MiniMap.ZoomOut']= 'When you change zones, automatically sets the minimap zoom to the level chosen in the submenu (fully zoomed out by default).',
    ['Tip.MiniMap.ZoomLevel']= 'Zoom level applied when you change zones. Click again to clear it. Also opens by right-clicking the zoom buttons.',
    ['Tip.MiniMap.InstanceDifficulty']= 'Replaces the minimap difficulty indicator with colored text showing the current instance difficulty. Requires a reload.',
    ['Tip.MiniMap.Collection']= 'Collects the addon icons of the minimap into a single button that shows them in a panel. When disabled, the sliders adjust the border and background of the icons on the minimap.',
    ['Tip.MiniMap.HideLanding']= 'Hides the expansion summary (garrison) button of the minimap. Requires a reload.',
    ['Tip.MiniMap.MoveLanding']= 'Lets you move the expansion summary (garrison) button with right-click. Requires a reload.',
    ['Tip.MiniMap.StopwatchClickPause']= 'Starts or pauses the stopwatch when you left-click it.',
    ['Tip.MiniMap.ClockPlus']= 'Improves the clock and stopwatch: move them (Alt+right-click), scale them (Alt+wheel), change background and strata, and remembers whether the stopwatch was open. Requires a reload.',
    ['Tip.MiniMap.TrackShowText']= 'Shows or hides the text list next to the tracking button. Also with Alt+wheel over the button.',
    ['Tip.MiniMap.VignetteMinimap']= 'Includes rare events (vignettes) visible on the minimap in the list.',
    ['Tip.MiniMap.VignetteWorldMap']= 'Includes rare events (vignettes) visible on the world map in the list.',
    ['Tip.MiniMap.VignetteSound']= 'Reads aloud (text to speech) the name of new rare events that appear. Silent while on a flight path.',
    ['Tip.MiniMap.TrackQuests']= 'World quests followed in the list. Add or remove them with Alt+left-click on the world map; you can remove them here.',
    ['Tip.MiniMap.TrackAreaPoi']= 'Points of interest followed in the list. Add or remove them with Alt+left-click on the world map; you can remove them here.',
    ['Tip.MiniMap.TrackMaps']= 'Maps whose points of interest are always shown in the list. Add them with the world map button; you can remove them here.',
    ['Tip.MiniMap.TrackTextDown']= 'Lists the text downwards instead of upwards.',
    ['Tip.MiniMap.CollectShow']= 'Shows or hides the panel with the collected icons. Also with Alt+wheel over the button.',
    ['Tip.MiniMap.CollectEnterShow']= 'Opens the icon panel when you mouse over the button.',
    ['Tip.MiniMap.CollectHideCombat']= 'Hides the icon panel when entering combat.',
    ['Tip.MiniMap.CollectHideMove']= 'Hides the icon panel when you start moving.',
    ['Tip.MiniMap.CollectSortUp']= 'Sorts the panel icons in ascending order.',
    ['Tip.MiniMap.CollectRefresh']= 'Searches for addon icons again and rebuilds the panel.',
    ['Tip.MiniMap.CollectFilters']= 'Choose the icons that are not collected and stay on the minimap.',
    ['Tip.MiniMap.CollectFilterItem']= 'Checked: this icon is not collected and stays on the minimap.',
    ['Tip.MiniMap.CollectHide']= 'Choose the icons that are hidden completely.',
    ['Tip.MiniMap.CollectHideItem']= 'Checked: this icon is hidden completely.',
    ['Tip.MiniMap.CollectCustom']= 'Adds other frames (buttons not from LibDBIcon) to the panel by their global name.',
    ['Tip.MiniMap.CollectAdd']= 'Enter a frame\'s global name (_G) to collect it into the panel. The Alt button of the dialog removes it. Use FSTACK to find the name.',
    ['Tip.MiniMap.CollectCustomItem']= 'Turns collecting this manually added frame on or off.',
    ['Tip.MiniMap.CollectCustomRemove']= 'Removes this frame from the custom list and puts it back in place.',
    ['Tip.Merchant.Module']= 'Improves the merchant window: auto-sells junk and chosen items, auto buyback and auto buy, auto repair, a wider window with item info and improved auto loot. Disabling it requires a reload.',
    ['Tip.Merchant.SellJunk']= 'When you open a merchant, automatically sells poor (gray) items, items in your custom list and flagged boss loot. Sells up to 11 stacks per visit; hold a modifier key to skip selling.',
    ['Tip.Merchant.SellCustom']= 'Also sells the items in your custom list when auto-selling. Add or remove items by dragging them from your bags onto the merchant\'s shopping cart button.',
    ['Tip.Merchant.SellBoss']= 'Records bound boss loot you receive in instances that is 30+ item levels below yours (or from older expansions) and sells it at merchants. Never sells uncollected appearances.',
    ['Tip.Merchant.SaveBossList']= 'Keeps the boss loot list when you log out; if disabled, it is cleared on logout.',
    ['Tip.Merchant.BuybackList']= 'Items that are never sold and are bought back automatically if you sell them. Add them by dragging onto the buyback button; you can remove them here.',
    ['Tip.Merchant.BuybackAll']= 'Buys back every item in the buyback tab (spends gold).',
    ['Tip.Merchant.BuybackItem']= 'Checked: this item will never be sold and will be bought back automatically if sold.',
    ['Tip.Merchant.AutoBuy']= 'When you open a merchant, automatically buys the items in your list up to the set amount (spends gold or currency). Add items by dragging them from the merchant onto the shopping cart button. Hold a modifier key to skip.',
    ['Tip.Merchant.SellMenu']= 'Sells at once the bag items of one quality, the reagents or everything (asks for confirmation). Does not sell legendary items or those in the buyback list.',
    ['Tip.Merchant.AutoRepair']= 'Automatically repairs all your gear when you open a merchant that can repair. Uses guild funds first when possible; hold a modifier key to skip.',
    ['Tip.Merchant.Plus']= 'Widens the merchant window to show more items per page and adds info to each item (level, stats, whether you have it in bags or bank).',
    ['Tip.Merchant.ButtonWidth']= 'Width of each item button in the merchant window.',
    ['Tip.Merchant.ItemsLayout']= 'Number of item rows and columns per page in the merchant window.',
    ['Tip.Merchant.ItemInfo']= 'Shows on each merchant item its level, stats and how many you have in bags and bank.',
    ['Tip.Merchant.UnusableAlpha']= 'Opacity of items you cannot use, cannot buy or have already collected.',
    ['Tip.Merchant.AutoLoot']= 'Adds a checkbox to the loot window to toggle auto loot and loots everything when it opens. Hold Shift to skip that time. Cannot be changed in combat. Requires a reload.',
    ['Tip.Encounter.Module']= 'Improves the Adventure Guide: loot specialization per boss, instance and Mythic+ data, renown list, bosses defeated and more. Always records boss kills.',
    ['Tip.Encounter.Journeys']= 'Shows the renown level and progress of each faction on the Journeys cards. Requires a reload.',
    ['Tip.Encounter.RenownList']= 'Shows a list of renown factions with their level and progress next to the Adventure Guide.',
    ['Tip.Encounter.RenownShowName']= 'Shows the faction name in the list for the checked expansions.',
    ['Tip.Encounter.RenownHideExpansion']= 'Hides the factions of the checked expansions from the list.',
    ['Tip.Encounter.Plus']= 'Adds info to the guide\'s bosses: how many times you defeated them, whether you own the loot appearances, item stats and icons on abilities (click to link them). Requires a reload.',
    ['Tip.Encounter.InstanceList']= 'Shows defeated bosses, Mythic+ data (score, best level, your keystone) on the instance list and lets you mark favorites. Requires a reload.',
    ['Tip.Encounter.LootSpec']= 'Adds per-class buttons on each boss to choose the loot specialization. When the fight starts it switches automatically and restores it when it ends. Requires a reload.',
    ['Tip.Encounter.LootOnlyClass']= 'Shows only your class button instead of those for every class. Requires a reload.',
    ['Tip.Encounter.LootSpecRadio']= 'Uses this loot specialization for this boss; applied when the fight starts and restored when it ends. Click again to clear it.',
    ['Tip.Encounter.LootSpecClearBoss']= 'Clears the saved loot specialization of every class for this boss (asks for confirmation).',
    ['Tip.Encounter.LootSpecClearClass']= 'Clears the saved loot specialization of this class for every boss (asks for confirmation).',
    ['Tip.Encounter.LootSpecClearAll']= 'Clears all saved loot specializations (asks for confirmation).',
    ['Tip.Encounter.SaveTier']= 'Remembers the expansion selected in the Adventure Guide and opens it there again (applied on reload).',
    ['Tip.Encounter.Favorite']= 'Adds or removes this instance from your favorites in the instance list.',
    ['Tip.Encounter.FavoriteClear']= 'Removes all favorite instances (asks for confirmation).',
    ['Tip.Encounter.KillDelete']= 'Deletes the count of times you defeated this boss (asks for confirmation).',
    ['Tip.Encounter.KillClearAll']= 'Deletes the defeat counters of every boss (asks for confirmation).',
    ['Tip.Mail.Module']= 'Improves the mailbox: info on each letter and buttons to delete or return, a recipient list (your characters, friends, guild and communities), send history and buttons to attach items by type. Disabling it requires a reload.',
    ['Tip.Mail.InBoxPlus']= 'Shows the items and money of each inbox letter, adds buttons to delete or return letters (one or all) and lets you reply to the sender with a click.',
    ['Tip.Mail.NameList']= 'Adds a menu next to the recipient field to choose among your characters, Battle.net friends, friends, guild and communities, plus a button to send to your target.',
    ['Tip.Mail.History']= 'Shows a list of the recipients you last sent mail to so you can pick them with one click.',
    ['Tip.Mail.HistoryShow']= 'Shows or hides the recent recipients list.',
    ['Tip.Mail.HistoryList']= 'Recipients saved in the history; uncheck one to remove it.',
    ['Tip.Mail.HistoryMax']= 'Maximum number of recipients kept in the history.',
    ['Tip.Mail.FastButtons']= 'Shows buttons per item type that attach every unbound item of that type from your bags to the mail. Right-click a button to assign it a recipient.',
    ['Tip.Mail.FastShow']= 'Shows or hides the buttons that attach items by type.',
    ['Tip.Mail.FastClass']= 'Attaches the unbound items of this category from your bags to the mail (weapons and armor only if their appearance is not collected).',
    ['Tip.Mail.FastRecipient']= 'Assigns this player to the button: clicking it fills in this recipient before attaching the items. Click again to remove it.',
    ['Tip.Mail.AutoSend']= 'When you open the mailbox and have no letters, automatically switches to the Send Mail tab after the set seconds.',
